def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    candidates = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        hh, ww = r1 - r0 + 1, c1 - c0 + 1
        area = hh * ww
        if hh < 5 or ww < 5 or area > 400:
            continue
        if any(grid[r0][c] != color or grid[r1][c] != color
               for c in range(c0, c1 + 1)):
            continue
        if any(grid[r][c0] != color or grid[r][c1] != color
               for r in range(r0, r1 + 1)):
            continue
        density = sum(grid[r][c] == color
                      for r in range(r0, r1 + 1)
                      for c in range(c0, c1 + 1)) / area
        if density >= 0.5:
            candidates.append((area, r0, c0, r1, c1, color))

    if not candidates:
        return [row[:] for row in grid]

    _, r0, c0, r1, c1, base = min(candidates)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(out), len(out[0])

    counts = Counter(v for row in out for v in row)
    holes = [v for v in counts if v != base]
    if not holes:
        return out
    hole_color = max(holes, key=counts.get)

    def components(cells):
        remaining = set(cells)
        result = []
        while remaining:
            start = remaining.pop()
            comp = {start}
            q = [start]
            while q:
                r, c = q.pop()
                for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if p in remaining:
                        remaining.remove(p)
                        comp.add(p)
                        q.append(p)
            result.append(comp)
        return result

    def shape_key(comp):
        pts = list(comp)
        variants = []
        for flip in (1, -1):
            for rot in range(4):
                transformed = []
                for r, c in pts:
                    x, y = r, flip * c
                    for _ in range(rot):
                        x, y = y, -x
                    transformed.append((x, y))
                mr = min(x for x, y in transformed)
                mc = min(y for x, y in transformed)
                variants.append(tuple(sorted((x-mr, y-mc)
                                             for x, y in transformed)))
        return min(variants)

    target = []
    for comp in components({(r, c) for r in range(H) for c in range(W)
                            if out[r][c] == hole_color}):
        target.append((comp, shape_key(comp)))

    # Collect colored objects outside the patterned rectangle.
    outside = defaultdict(list)
    for color in colors - {base, hole_color}:
        cells = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color and
                 not (r0 <= r <= r1 and c0 <= c <= c1)}
        for comp in components(cells):
            outside[shape_key(comp)].append((color, comp))

    for comp, key in target:
        matches = outside.get(key, [])
        if not matches:
            continue
        votes = Counter(color for color, _ in matches)
        chosen = votes.most_common(1)[0][0]
        for r, c in comp:
            out[r][c] = chosen

    return out
